`timescale 1ns / 1ps
`default_nettype none

// Terasic DE10-Lite (MAX 10) demo wrapper for vibmon_top.
//
// No sensor is needed for the demo: synthetic accelerometer recordings of
// five machine conditions (generated by `python -m vibmodel generate`) are
// stored in on-chip ROM and played back at 4 kHz in a loop.
//
//   SW[2:0]  scenario: 0 healthy, 1 imbalance, 2 misalignment,
//            3 looseness, 4 bearing defect
//   KEY[0]   reset
//   LEDR[2c]   channel c at WARNING or above   (c: 0 overall, 1 1x, 2 2x,
//   LEDR[2c+1] channel c CRITICAL                   3 harmonics, 4 bearing)
//   VGA      live bar-graph display
//
// Port names follow the DE10-Lite System Builder golden top; generate the
// pin assignments with Terasic's System Builder. Not yet tested on hardware.
module de10lite_top (
    input  wire       MAX10_CLK1_50,
    input  wire [1:0] KEY,
    input  wire [9:0] SW,
    output wire [9:0] LEDR,
    output wire [3:0] VGA_R,
    output wire [3:0] VGA_G,
    output wire [3:0] VGA_B,
    output wire       VGA_HS,
    output wire       VGA_VS
);
    `include "vib_params.vh"

    localparam integer ROM_LEN    = 4096;
    localparam integer N_SCEN     = 5;
    localparam integer CLKS_PER_S = 12_500;        // 50 MHz / 4 kHz
    localparam [3:0]   PERSIST4   = VIB_PERSIST;

    wire clk = MAX10_CLK1_50;

    // reset: KEY[0] (active low), synchronised
    reg [1:0] rst_sync = 2'b11;
    always @(posedge clk) rst_sync <= {rst_sync[0], !KEY[0]};
    wire rst = rst_sync[1];

    // 4 kHz sample tick
    reg [13:0] div = 14'd0;
    reg        tick = 1'b0;
    always @(posedge clk) begin
        tick <= 1'b0;
        if (rst) begin
            div <= 14'd0;
        end else if (div == CLKS_PER_S - 1) begin
            div  <= 14'd0;
            tick <= 1'b1;
        end else begin
            div <= div + 14'd1;
        end
    end

    // demo ROM: N_SCEN recordings of ROM_LEN samples
    reg [15:0] rom [0:N_SCEN * ROM_LEN - 1];
    initial $readmemh("vib_demo.hex", rom);

    reg  [11:0] idx = 12'd0;
    wire [2:0]  scen = (SW[2:0] < N_SCEN) ? SW[2:0] : 3'd0;
    reg  [15:0] sample;
    reg         sample_valid = 1'b0;
    always @(posedge clk) begin
        sample_valid <= tick;                          // ROM read takes one clock
        sample       <= rom[{scen, idx}];
        if (tick) idx <= idx + 12'd1;
    end

    wire [VIB_N_CH*2-1:0] level;
    wire [VIB_N_CH*32-1:0] energy;
    wire [1:0] overall;
    wire block_valid, overrun, vga_de;

    vibmon_top #(.CLK_DIV(2), .NCH(VIB_N_CH)) u_mon (
        .clk(clk), .rst(rst), .sample_valid(sample_valid), .sample(sample),
        .warn_th(VIB_WARN), .crit_th(VIB_CRIT), .persist(PERSIST4),
        .block_valid(block_valid), .energy(energy), .level(level), .overall(overall),
        .overrun(overrun),
        .vga_r(VGA_R), .vga_g(VGA_G), .vga_b(VGA_B),
        .vga_hs(VGA_HS), .vga_vs(VGA_VS), .vga_de(vga_de));

    genvar c;
    generate
        for (c = 0; c < VIB_N_CH; c = c + 1) begin : g_led
            assign LEDR[2 * c]     = level[2 * c +: 2] >= 2'd1;
            assign LEDR[2 * c + 1] = level[2 * c +: 2] == 2'd2;
        end
    endgenerate
endmodule

`default_nettype wire
